import re

def calculate(expression):
    def apply_operator(operators, operands):
        operator = operators.pop()
        right = operands.pop()
        left = operands.pop()
        if operator == '+':
            operands.append(left + right)
        elif operator == '-':
            operands.append(left - right)
        elif operator == '*':
            operands.append(left * right)
        elif operator == '/':
            operands.append(left / right)

    def precedence(op):
        if op == '+' or op == '-':
            return 1
        elif op == '*' or op == '/':
            return 2
        return 0

    tokens = re.findall(r'\d+|\+|\-|\*|\/|\(|\)', expression)
    numbers = []
    operators = []

    for token in tokens:
        if token.isdigit():
            numbers.append(float(token))
        elif token in '+-*/':
            while (operators and operators[-1] != '(' and precedence(token) <= precedence(operators[-1])):
                apply_operator(operators, numbers)
            operators.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                apply_operator(operators, numbers)
            operators.pop()

    while operators:
        apply_operator(operators, numbers)

    return numbers[0]

# Example usage:
expression = "2 + 3 * (4 - 1)"
result = calculate(expression)
print(result)  # Output: 9.0
